H.background();
const cx = H.W * 0.42, cy = H.H * 0.56;
const m = P.m, r = P.r, L = P.L;
// L = I omega with I = m r^2  ->  omega = L / (m r^2). Conserving L: small r -> big omega.
const I = m * r * r;
const omega = I > 1e-6 ? L / I : 0;          // omega = L / (m r^2)
const scale = 46;                            // px per metre
const Rpx = r * scale;
const ang = (omega * t) % H.TAU;             // spins at the real omega, wrapped
// rotation axis
H.circle(cx, cy, 6, { fill: H.colors.axis });
H.circle(cx, cy, Rpx, { stroke: H.colors.grid, width: 1 });
// two symmetric masses (the skater's hands) at radius r
for (let s = 0; s < 2; s++) {
  const a = ang + s * Math.PI;
  const mx = cx + Rpx * Math.cos(a), my = cy - Rpx * Math.sin(a);
  H.line(cx, cy, mx, my, { color: H.colors.accent, width: 3 });
  H.circle(mx, my, 9, { fill: H.colors.warn });
  // tangential velocity arrow v = omega r
  const vmag = H.clamp(omega * r * 14, -90, 90);
  H.arrow(mx, my, mx - vmag * Math.sin(a), my - vmag * Math.cos(a), { color: H.colors.good, width: 2.5 });
}
// L bar (should stay ~constant as you change r — that's the point)
const bx = 28, by = H.H - 42, bw = H.clamp(L * 24, 2, H.W - 60);
H.rect(bx, by, bw, 16, { fill: H.colors.violet, radius: 4 });
H.text("L (conserved)", bx, by - 6, { color: H.colors.sub, size: 12 });
H.text("Angular momentum:  L = I * omega = m r^2 * omega", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("m = " + m.toFixed(1) + " kg   r = " + r.toFixed(2) + " m   L = " + L.toFixed(2) + " kg·m²/s", 24, 52, { color: H.colors.sub, size: 13 });
H.text("pull arms in (small r) → omega = " + omega.toFixed(2) + " rad/s  (spins faster)", 24, 72, { color: H.colors.accent2, size: 13 });
H.legend([{ label: "mass m", color: H.colors.warn }, { label: "v = omega·r", color: H.colors.good }, { label: "L stays fixed", color: H.colors.violet }], H.W - 185, 28);
